AI_ROLE_MODULE = 'from __future__ import annotations\n\nimport re\nfrom typing import Any\n\nfrom django.db.models import Q\n\nfrom . import models as m\n\n\nADMIN = "admin"\nOFFICE = "office"\nPROJECT_MANAGER = "project_manager"\nTECHNICIAN = "technician"\nACCOUNTING = "accounting"\nREADONLY = "readonly"\n\nPRICE_ROLES = {ADMIN, OFFICE, ACCOUNTING}\nFIELD_AI_ROLES = {ADMIN, OFFICE, PROJECT_MANAGER, TECHNICIAN}\nROOM_AI_ROLES = {ADMIN, OFFICE, PROJECT_MANAGER, TECHNICIAN}\nDRAFT_MUTATION_ROLES = {ADMIN, OFFICE, PROJECT_MANAGER, TECHNICIAN, ACCOUNTING}\n\n_ALL_ROUTES = {\n    "dashboard", "customers", "projects", "appointments", "tasks", "quotes",\n    "invoices", "expenses", "time", "employees", "settings", "field",\n}\n_ROUTE_POLICY = {\n    ADMIN: _ALL_ROUTES,\n    OFFICE: _ALL_ROUTES - {"settings"},\n    ACCOUNTING: {"dashboard", "customers", "projects", "quotes", "invoices", "expenses"},\n    # Project managers get record-level KI navigation only; the generic rebuilt\n    # list pages are broader than their assignment scope.\n    PROJECT_MANAGER: {"dashboard", "field"},\n    TECHNICIAN: {"dashboard", "projects", "appointments", "tasks", "time", "field"},\n    READONLY: {"dashboard", "customers", "projects", "appointments", "tasks"},\n}\n_SEARCH_ROUTE_POLICY = {\n    ADMIN: {"employees", "customers", "projects", "appointments"},\n    OFFICE: {"employees", "customers", "projects", "appointments"},\n    ACCOUNTING: {"customers", "projects"},\n    PROJECT_MANAGER: {"employees", "customers", "projects", "appointments"},\n    TECHNICIAN: {"employees", "customers", "projects", "appointments"},\n    READONLY: {"customers", "projects", "appointments"},\n}\n\n_RECORD_ROUTE_POLICY = {\n    ADMIN: {"employees", "customers", "projects", "appointments", "tasks", "quotes", "invoices", "expenses"},\n    OFFICE: {"employees", "customers", "projects", "appointments", "tasks", "quotes", "invoices", "expenses"},\n    ACCOUNTING: {"customers", "projects", "quotes", "invoices", "expenses"},\n    PROJECT_MANAGER: {"employees", "customers", "projects", "appointments", "tasks"},\n    TECHNICIAN: {"employees", "customers", "projects", "appointments", "tasks"},\n    READONLY: {"customers", "projects", "appointments", "tasks"},\n}\n\n_PRICE_TOKEN_RE = re.compile(\n    r"(?i)(?:"\n    r"\\bpreis(?:e|en|lich)?\\b|\\bkosten\\b|\\bkostet\\b|\\beinkauf(?:spreis)?\\b|\\bverkauf(?:spreis)?\\b|"\n    r"\\bek\\b|\\bvk\\b|\\bmarge\\b|\\bmargin\\b|\\bmarkup\\b|\\baufschlag\\b|\\bgewinn\\b|\\bprofit\\b|"\n    r"\\bumsatz\\b|\\brevenue\\b|\\bstundensatz\\b|\\bverrechnungssatz\\b|\\bnetto\\b|\\bbrutto\\b|"\n    r"\\bunit[_ -]?price\\b|\\bsales[_ -]?price\\b|\\bpurchase[_ -]?price\\b|\\bprice\\b|\\bcosts?\\b|"\n    r"\\bamount\\b|\\btotal\\b|\\bvat\\b|\\bmwst\\b|€|\\beur\\b|\\beuro\\b"\n    r")"\n)\n_SENSITIVE_FIELD_RE = re.compile(\n    r"(?i)(?:"\n    r"preis|price|kosten|cost|einkauf|verkauf|purchase|sales|"\n    r"marge|margin|markup|aufschlag|gewinn|profit|umsatz|revenue|"\n    r"stundensatz|hourly[_ -]?(?:cost|rate)|verrechnung|"\n    r"netto|brutto|amount|total|summe|vat|mwst|tax[_ -]?rate"\n    r")"\n)\n_INTERNAL_FIELD_RE = re.compile(\n    r"(?i)(?:purchase|einkauf|hourly[_ -]?cost|interner[_ -]?stundensatz|"\n    r"marge|margin|markup|aufschlag|gewinn|profit)"\n)\n\n\ndef role_for(user) -> str:\n    if getattr(user, "is_superuser", False):\n        return ADMIN\n    try:\n        profile = user.profile\n    except Exception:\n        return READONLY\n    role = str(getattr(profile, "role", "") or READONLY)\n    # A non-admin mobile worker is deliberately treated like field staff for KI.\n    # This prevents an accidentally broad office role from becoming a mobile data bypass.\n    if role != ADMIN and bool(getattr(profile, "is_mobile_worker", False)):\n        return TECHNICIAN\n    return role if role in {ADMIN, OFFICE, PROJECT_MANAGER, TECHNICIAN, ACCOUNTING, READONLY} else READONLY\n\n\ndef can_view_prices(user) -> bool:\n    return role_for(user) in PRICE_ROLES\n\n\ndef can_view_internal_prices(user) -> bool:\n    return role_for(user) in PRICE_ROLES\n\n\ndef can_use_field_ai(user) -> bool:\n    return role_for(user) in FIELD_AI_ROLES\n\n\ndef can_use_room_ai(user) -> bool:\n    return role_for(user) in ROOM_AI_ROLES\n\n\ndef can_mutate_ai_drafts(user) -> bool:\n    return role_for(user) in DRAFT_MUTATION_ROLES\n\n\ndef allowed_navigation_routes(user) -> set[str]:\n    role = role_for(user)\n    return set(_ROUTE_POLICY.get(role, {"dashboard"}))\n\n\ndef allowed_search_routes(user) -> set[str]:\n    role = role_for(user)\n    return set(_SEARCH_ROUTE_POLICY.get(role, set()))\n\n\ndef allowed_record_routes(user) -> set[str]:\n    role = role_for(user)\n    return set(_RECORD_ROUTE_POLICY.get(role, set()))\n\n\ndef employee_for(user, organization):\n    if not getattr(user, "is_authenticated", False):\n        return None\n    employee = m.Employee.objects.filter(organization=organization, user=user, active=True).first()\n    if employee is not None:\n        return employee\n    email = (getattr(user, "email", "") or "").strip()\n    if email:\n        return m.Employee.objects.filter(organization=organization, email__iexact=email, active=True).first()\n    return None\n\n\ndef project_queryset(user, organization):\n    base = m.Project.objects.filter(organization=organization, archived=False)\n    role = role_for(user)\n    if role in {ADMIN, OFFICE, ACCOUNTING, READONLY}:\n        return base\n    employee = employee_for(user, organization)\n    if employee is None:\n        return base.none()\n    event_project_ids = m.CalendarEvent.objects.filter(\n        organization=organization, attendees=employee, project_id__isnull=False\n    ).values_list("project_id", flat=True)\n    return base.filter(\n        Q(manager=employee) | Q(members=employee) | Q(pk__in=event_project_ids)\n    ).distinct()\n\n\ndef event_queryset(user, organization):\n    base = m.CalendarEvent.objects.filter(organization=organization)\n    role = role_for(user)\n    if role in {ADMIN, OFFICE, READONLY}:\n        return base\n    if role == ACCOUNTING:\n        return base.none()\n    employee = employee_for(user, organization)\n    if employee is None:\n        return base.none()\n    projects = project_queryset(user, organization).values_list("pk", flat=True)\n    return base.filter(Q(attendees=employee) | Q(project_id__in=projects)).distinct()\n\n\ndef customer_queryset(user, organization):\n    base = m.Customer.objects.filter(organization=organization, active=True)\n    role = role_for(user)\n    if role in {ADMIN, OFFICE, ACCOUNTING, READONLY}:\n        return base\n    project_customer_ids = project_queryset(user, organization).exclude(\n        customer_id__isnull=True\n    ).values_list("customer_id", flat=True)\n    return base.filter(pk__in=project_customer_ids).distinct()\n\n\ndef employee_queryset(user, organization):\n    base = m.Employee.objects.filter(organization=organization, active=True)\n    role = role_for(user)\n    if role in {ADMIN, OFFICE}:\n        return base\n    employee = employee_for(user, organization)\n    if employee is None:\n        return base.none()\n    if role == TECHNICIAN:\n        return base.filter(pk=employee.pk)\n    if role == ACCOUNTING:\n        return base.none()\n    if role == READONLY:\n        return base.none()\n    projects = project_queryset(user, organization)\n    manager_ids = projects.exclude(manager_id__isnull=True).values_list("manager_id", flat=True)\n    member_ids = m.Employee.objects.filter(projects__in=projects).values_list("pk", flat=True)\n    return base.filter(Q(pk=employee.pk) | Q(pk__in=manager_ids) | Q(pk__in=member_ids)).distinct()\n\n\ndef task_queryset(user, organization):\n    base = m.Task.objects.filter(organization=organization)\n    role = role_for(user)\n    if role in {ADMIN, OFFICE, READONLY}:\n        return base\n    if role == ACCOUNTING:\n        return base.none()\n    employee = employee_for(user, organization)\n    if employee is None:\n        return base.none()\n    projects = project_queryset(user, organization).values_list("pk", flat=True)\n    if role == TECHNICIAN:\n        return base.filter(Q(assigned_to=employee) | Q(project_id__in=projects, assigned_to=employee)).distinct()\n    return base.filter(Q(assigned_to=employee) | Q(project_id__in=projects)).distinct()\n\n\ndef project_allowed(user, organization, project_id) -> bool:\n    try:\n        project_id = int(project_id)\n    except (TypeError, ValueError):\n        return False\n    return project_queryset(user, organization).filter(pk=project_id).exists()\n\n\ndef event_allowed(user, organization, event_id) -> bool:\n    try:\n        event_id = int(event_id)\n    except (TypeError, ValueError):\n        return False\n    return event_queryset(user, organization).filter(pk=event_id).exists()\n\n\ndef record_allowed(user, organization, route: str, record_id) -> bool:\n    route = str(route or "")\n    try:\n        record_id = int(record_id)\n    except (TypeError, ValueError):\n        return False\n    if route == "projects":\n        return project_queryset(user, organization).filter(pk=record_id).exists()\n    if route == "customers":\n        return customer_queryset(user, organization).filter(pk=record_id).exists()\n    if route == "appointments":\n        return event_queryset(user, organization).filter(pk=record_id).exists()\n    if route == "employees":\n        return employee_queryset(user, organization).filter(pk=record_id).exists()\n    if route == "tasks":\n        return task_queryset(user, organization).filter(pk=record_id).exists()\n    if route == "quotes":\n        return role_for(user) in {ADMIN, OFFICE, ACCOUNTING} and m.Quote.objects.filter(\n            organization=organization, pk=record_id\n        ).exists()\n    if route == "invoices":\n        return role_for(user) in {ADMIN, OFFICE, ACCOUNTING} and m.Invoice.objects.filter(\n            organization=organization, pk=record_id\n        ).exists()\n    if route == "expenses":\n        return role_for(user) in {ADMIN, OFFICE, ACCOUNTING} and m.Expense.objects.filter(\n            organization=organization, pk=record_id\n        ).exists()\n    return False\n\n\ndef is_price_request(message: str) -> bool:\n    return bool(_PRICE_TOKEN_RE.search(message or ""))\n\n\ndef is_sensitive_field(name: str, label: str = "") -> bool:\n    return bool(_SENSITIVE_FIELD_RE.search(f"{name or \'\'} {label or \'\'}"))\n\n\ndef is_internal_price_field(name: str, label: str = "") -> bool:\n    return bool(_INTERNAL_FIELD_RE.search(f"{name or \'\'} {label or \'\'}"))\n\n\ndef _option_scope(field_name: str):\n    normalized = (field_name or "").casefold()\n    if normalized in {"customer", "customer_id", "kunde", "kunde_id"}:\n        return "customers"\n    if normalized in {"project", "project_id", "projekt", "projekt_id"}:\n        return "projects"\n    if normalized in {\n        "assigned_to", "assigned_to_id", "manager", "manager_id", "members",\n        "members_id", "attendees", "attendees_id", "employee", "employee_id",\n    }:\n        return "employees"\n    return ""\n\n\ndef _allowed_ids_for_route(user, organization, route: str) -> set[str]:\n    if route == "customers":\n        qs = customer_queryset(user, organization)\n    elif route == "projects":\n        qs = project_queryset(user, organization)\n    elif route == "employees":\n        qs = employee_queryset(user, organization)\n    elif route == "appointments":\n        qs = event_queryset(user, organization)\n    else:\n        return set()\n    return {str(value) for value in qs.values_list("pk", flat=True)}\n\n\ndef sanitize_assistant_payload(user, organization, payload: dict[str, Any]) -> dict[str, Any]:\n    safe: dict[str, Any] = {}\n    if not isinstance(payload, dict):\n        return safe\n    for key in ("message", "path", "title"):\n        if key in payload:\n            safe[key] = payload.get(key)\n\n    price_ok = can_view_prices(user)\n    fields = []\n    for raw in (payload.get("fields") or [])[:80]:\n        if not isinstance(raw, dict):\n            continue\n        name = str(raw.get("name") or "")[:120]\n        label = str(raw.get("label") or "")[:220]\n        if not price_ok and is_sensitive_field(name, label):\n            continue\n        item = dict(raw)\n        route = _option_scope(name)\n        if route:\n            allowed_ids = _allowed_ids_for_route(user, organization, route)\n            options = []\n            for option in (raw.get("options") or [])[:100]:\n                if not isinstance(option, dict):\n                    continue\n                value = str(option.get("value") or "")\n                if not value or value in allowed_ids:\n                    options.append(option)\n            item["options"] = options\n            current = str(item.get("value") or "")\n            if current and current.isdigit() and current not in allowed_ids:\n                item["value"] = ""\n        fields.append(item)\n    safe["fields"] = fields\n\n    catalog = []\n    # Catalog names/codes/units may help field staff document work, but prices never\n    # cross the boundary unless the role has explicit commercial permission.\n    if role_for(user) in {ADMIN, OFFICE, PROJECT_MANAGER, TECHNICIAN}:\n        for raw in (payload.get("catalog") or [])[:160]:\n            if not isinstance(raw, dict):\n                continue\n            item = dict(raw)\n            if not price_ok:\n                for key in list(item):\n                    if is_sensitive_field(str(key), str(key)):\n                        item.pop(key, None)\n            catalog.append(item)\n    safe["catalog"] = catalog\n\n    # Client history is untrusted after a role downgrade. Admin can keep it; every\n    # other role gets server-scoped entity continuity instead of replaying old text.\n    safe["history"] = (payload.get("history") or [])[-10:] if role_for(user) == ADMIN else []\n    return safe\n\n\ndef entity_search_context(user, organization, message: str) -> list[dict[str, Any]]:\n    raw = re.findall(r"[\\w@.+-]+", message or "", flags=re.UNICODE)\n    stopwords = {\n        "find", "search", "show", "open", "go", "to", "for", "the", "a", "an",\n        "finde", "finden", "suche", "suchen", "zeig", "zeige", "öffne", "offne", "geh", "gehe", "nach",\n        "mitarbeiter", "employee", "employees", "kunde", "kunden", "customer", "customers", "client", "clients",\n        "projekt", "projekte", "project", "projects", "termin", "termine", "appointment", "appointments",\n        "auftrag", "aufträge", "auftrage", "einsatz", "einsätze", "einsatze",\n    }\n    terms = []\n    for token in raw:\n        normalized = token.casefold().strip("._-+")\n        if len(normalized) < 2 or normalized in stopwords:\n            continue\n        terms.append(token[:80])\n    terms = terms[:6]\n    if not terms:\n        return []\n\n    def and_query(fields):\n        combined = Q()\n        for term in terms:\n            per_term = Q()\n            for field in fields:\n                per_term |= Q(**{f"{field}__icontains": term})\n            combined &= per_term\n        return combined\n\n    allowed = allowed_search_routes(user)\n    matches: list[dict[str, Any]] = []\n\n    if "employees" in allowed:\n        qs = employee_queryset(user, organization).filter(\n            and_query(("first_name", "last_name", "email", "phone", "employee_number", "trade"))\n        ).order_by("-active", "last_name", "first_name")[:8]\n        role = role_for(user)\n        for item in qs:\n            detail_parts = [item.employee_number, item.trade]\n            if role in {ADMIN, OFFICE}:\n                detail_parts.insert(1, item.email)\n            matches.append({\n                "route": "employees", "id": item.pk,\n                "label": f"{item.first_name} {item.last_name}".strip() or item.employee_number,\n                "detail": " · ".join(part for part in detail_parts if part),\n            })\n\n    if "customers" in allowed:\n        qs = customer_queryset(user, organization).filter(\n            and_query(("company", "first_name", "last_name", "email", "phone", "mobile", "number"))\n        ).order_by("-updated_at")[:8]\n        role = role_for(user)\n        for item in qs:\n            detail_parts = [item.number, item.city]\n            if role in {ADMIN, OFFICE, ACCOUNTING}:\n                detail_parts.insert(1, item.email)\n            matches.append({\n                "route": "customers", "id": item.pk, "label": item.display_name,\n                "detail": " · ".join(part for part in detail_parts if part),\n            })\n\n    if "projects" in allowed:\n        qs = project_queryset(user, organization).filter(\n            and_query(("number", "title", "description", "customer__company", "customer__first_name", "customer__last_name"))\n        ).select_related("customer").order_by("-updated_at")[:8]\n        for item in qs:\n            matches.append({\n                "route": "projects", "id": item.pk, "label": f"{item.number} · {item.title}",\n                "detail": item.customer.display_name if item.customer_id else "",\n            })\n\n    if "appointments" in allowed:\n        qs = event_queryset(user, organization).filter(\n            and_query(("title", "location", "notes", "project__title", "project__number"))\n        ).order_by("-starts_at")[:6]\n        for item in qs:\n            matches.append({\n                "route": "appointments", "id": item.pk, "label": item.title,\n                "detail": item.starts_at.strftime("%d.%m.%Y %H:%M") if item.starts_at else "",\n            })\n    return matches[:20]\n\n\ndef filter_results(user, organization, results):\n    safe = []\n    for item in results or []:\n        if not isinstance(item, dict):\n            continue\n        route = str(item.get("route") or "")\n        record_id = item.get("id")\n        if route in allowed_search_routes(user) and record_allowed(user, organization, route, record_id):\n            safe.append(item)\n    return safe[:20]\n\n\ndef filter_actions(user, organization, payload: dict[str, Any], actions):\n    field_names = {\n        str(field.get("name") or "")\n        for field in (payload.get("fields") or [])\n        if isinstance(field, dict)\n    }\n    routes = allowed_navigation_routes(user)\n    mutate = can_mutate_ai_drafts(user)\n    catalog_available = bool(payload.get("catalog"))\n    safe = []\n    for action in actions or []:\n        if not isinstance(action, dict):\n            continue\n        kind = str(action.get("type") or "")\n        target = str(action.get("target") or "")\n        value = str(action.get("value") or "")\n        if kind == "none":\n            safe.append(action)\n        elif kind in {"set_field", "select_option"}:\n            if mutate and target in field_names and not (not can_view_prices(user) and is_sensitive_field(target, target)):\n                safe.append(action)\n        elif kind == "focus":\n            if target in field_names:\n                safe.append(action)\n        elif kind == "catalog_add":\n            if mutate and catalog_available and role_for(user) in {ADMIN, OFFICE, PROJECT_MANAGER, TECHNICIAN}:\n                safe.append(action)\n        elif kind == "navigate":\n            if target in routes:\n                safe.append(action)\n        elif kind == "navigate_record":\n            if target in allowed_record_routes(user) and record_allowed(user, organization, target, value):\n                safe.append(action)\n    return safe[:14]\n\n\ndef sanitize_reply(user, reply: str) -> str:\n    text = str(reply or "")\n    if not can_view_prices(user) and _PRICE_TOKEN_RE.search(text):\n        return "Auf Preisdaten, Einkauf, Verkauf, Margen und finanzielle Kennzahlen hast du mit deiner Rolle über KAYI KI keinen Zugriff."\n    return text\n\n\ndef strip_sensitive_data(user, value):\n    if can_view_prices(user):\n        return value\n    if isinstance(value, dict):\n        clean = {}\n        for key, item in value.items():\n            if is_sensitive_field(str(key), str(key)):\n                continue\n            clean[key] = strip_sensitive_data(user, item)\n        return clean\n    if isinstance(value, list):\n        return [strip_sensitive_data(user, item) for item in value]\n    if isinstance(value, tuple):\n        return tuple(strip_sensitive_data(user, item) for item in value)\n    if isinstance(value, str):\n        return sanitize_reply(user, value)\n    return value\n\n\ndef route_for_path(path: str) -> str:\n    clean = str(path or "").split("?", 1)[0].strip()\n    if clean in {"", "/"}:\n        return "dashboard"\n    first = clean.strip("/").split("/", 1)[0]\n    mapping = {\n        "customers": "customers",\n        "projects": "projects",\n        "appointments": "appointments",\n        "tasks": "tasks",\n        "quotes": "quotes",\n        "invoices": "invoices",\n        "expenses": "expenses",\n        "time": "time",\n        "employees": "employees",\n        "settings": "settings",\n        "field": "field",\n    }\n    return mapping.get(first, "")\n\n\ndef assistant_path_allowed(user, organization, path: str) -> bool:\n    route = route_for_path(path)\n    if not route or route in allowed_navigation_routes(user):\n        return True\n    clean = str(path or "").split("?", 1)[0].strip("/")\n    parts = clean.split("/") if clean else []\n    if len(parts) >= 2 and parts[1].isdigit() and route in allowed_record_routes(user):\n        return record_allowed(user, organization, route, parts[1])\n    return False\n'

ASSISTANT_APPEND = '\n# A_BAU_AI_ROLE_SCOPE_HARDENING 2026-08-12\nfrom . import ai_role_permissions as _ai_perm\n\n_ab_role_original_assistant_command = assistant_command\n_ab_role_original_appointment_voice = appointment_voice\n\n\ndef _resolve_entity_search(request, organization, message: str) -> dict[str, Any]:\n    """Role-scoped entity resolution; never trust matches stored under an older role."""\n    route = _requested_entity_route(message)\n    terms = _search_terms(message)\n    has_lookup = _has_entity_lookup_verb(message)\n    previous = request.session.get("kayi_ai_entity_state") or {}\n    previous_query = str(previous.get("query") or "").strip()\n\n    followup = bool(route and not terms and not has_lookup and previous_query)\n    needs_query = bool(route and has_lookup and not terms)\n\n    if terms:\n        query = " ".join(terms)\n        broad_matches = _ai_perm.entity_search_context(request.user, organization, query)\n    elif followup:\n        query = previous_query\n        # Re-query under the CURRENT role. Stored result payloads are never reused,\n        # which prevents a role downgrade from replaying old admin/office matches.\n        broad_matches = _ai_perm.entity_search_context(request.user, organization, previous_query)\n    else:\n        query = ""\n        broad_matches = [] if needs_query else _ai_perm.entity_search_context(request.user, organization, message)\n\n    request.session["kayi_ai_entity_state"] = {\n        "query": query[:300],\n        "matches": broad_matches[:20],\n        "role": _ai_perm.role_for(request.user),\n        "updated_at": timezone.now().isoformat(),\n    }\n    request.session.modified = True\n\n    matches = _filter_entity_matches(broad_matches, route)\n    return {\n        "route": route,\n        "query": query,\n        "matches": matches[:20],\n        "broad_matches": broad_matches[:20],\n        "followup": followup,\n        "needs_query": needs_query,\n        "lookup": has_lookup,\n        "open": _has_entity_open_verb(message),\n    }\n\n\n@login_required\n@require_POST\ndef assistant_command(request):\n    try:\n        payload = json.loads(request.body.decode("utf-8"))\n    except (UnicodeDecodeError, json.JSONDecodeError):\n        return _ab_role_original_assistant_command(request)\n\n    organization = _org(request)\n    message = str(payload.get("message") or "").strip()\n\n    if not _ai_perm.assistant_path_allowed(request.user, organization, str(payload.get("path") or "")):\n        return JsonResponse(\n            {"ok": False, "error": "KAYI KI ist auf diesem Bereich für deine Rolle nicht freigeschaltet."},\n            status=403,\n        )\n\n    # Hard stop before any model/database AI context is built. No LLM is called.\n    if not _ai_perm.can_view_prices(request.user) and _ai_perm.is_price_request(message):\n        return JsonResponse(\n            {\n                "ok": False,\n                "error": "Auf Preisdaten, Einkauf, Verkauf, Margen und finanzielle Kennzahlen hast du mit deiner Rolle über KAYI KI keinen Zugriff.",\n                "permission_denied": True,\n            },\n            status=403,\n        )\n\n    safe_payload = _ai_perm.sanitize_assistant_payload(request.user, organization, payload)\n    original_body = request.body\n    request._body = json.dumps(safe_payload, ensure_ascii=False).encode("utf-8")\n    try:\n        response = _ab_role_original_assistant_command(request)\n    finally:\n        request._body = original_body\n\n    if response.status_code >= 400:\n        return response\n    try:\n        data = json.loads(response.content.decode("utf-8"))\n    except Exception:\n        return response\n\n    data["actions"] = _ai_perm.filter_actions(\n        request.user, organization, safe_payload, data.get("actions") or []\n    )\n    data["results"] = _ai_perm.filter_results(\n        request.user, organization, data.get("results") or []\n    )\n    data["reply"] = _ai_perm.sanitize_reply(request.user, str(data.get("reply") or ""))\n    return JsonResponse(data, status=response.status_code)\n\n\n@login_required\n@require_POST\ndef appointment_voice(request, pk):\n    organization = _org(request)\n    if not _ai_perm.can_use_field_ai(request.user):\n        return JsonResponse({"ok": False, "error": "KI-Sprachauswertung ist für deine Rolle nicht freigeschaltet."}, status=403)\n    if not _ai_perm.event_allowed(request.user, organization, pk):\n        # Deliberately do not reveal whether an out-of-scope event exists.\n        return JsonResponse({"ok": False, "error": "Einsatz nicht gefunden."}, status=404)\n    return _ab_role_original_appointment_voice(request, pk)\n'
FIELD_APPEND = '\n# A_BAU_AI_ROLE_SCOPE_HARDENING 2026-08-12\nfrom . import ai_role_permissions as _ai_perm\n\n_ab_role_original_authorization_ai = authorization_ai\n\n\n@login_required\n@require_POST\ndef authorization_ai(request, pk):\n    organization = _org(request)\n    if not _ai_perm.can_use_field_ai(request.user):\n        return JsonResponse({"ok": False, "error": "KAYI KI ist für diesen Arbeitsbereich nicht freigeschaltet."}, status=403)\n    if not _ai_perm.event_allowed(request.user, organization, pk):\n        return JsonResponse({"ok": False, "error": "Einsatz nicht gefunden."}, status=404)\n\n    response = _ab_role_original_authorization_ai(request, pk)\n    if response.status_code >= 400 or _ai_perm.can_view_prices(request.user):\n        return response\n    try:\n        data = json.loads(response.content.decode("utf-8"))\n    except Exception:\n        return response\n\n    # The old field KI enriches suggested catalog positions with sales_price/tax.\n    # Remove ALL commercial fields at the server boundary for field roles.\n    data = _ai_perm.strip_sensitive_data(request.user, data)\n    if isinstance(data, dict):\n        data["pricing_locked"] = True\n        data["requires_office_pricing"] = True\n    return JsonResponse(data, status=response.status_code)\n'
ROOM_APPEND = '\n# A_BAU_AI_ROLE_SCOPE_HARDENING 2026-08-12\nfrom . import ai_role_permissions as _ai_perm\nfrom .rebuild_views import _org as _ai_role_org\n\n_ab_role_original_room_planner_vision = room_planner_vision\n_ab_role_original_room_planner_ai = globals().get("room_planner_ai")\n\n\n@login_required\n@require_POST\ndef room_planner_vision(request, project_pk):\n    organization = _ai_role_org(request)\n    if not _ai_perm.can_use_room_ai(request.user):\n        return JsonResponse({"ok": False, "error": "Raum-KI ist für deine Rolle nicht freigeschaltet."}, status=403)\n    if not _ai_perm.project_allowed(request.user, organization, project_pk):\n        return JsonResponse({"ok": False, "error": "Projekt nicht gefunden."}, status=404)\n    return _ab_role_original_room_planner_vision(request, project_pk)\n\n\nif _ab_role_original_room_planner_ai is not None:\n    @login_required\n    @require_POST\n    def room_planner_ai(request, project_pk):\n        organization = _ai_role_org(request)\n        if not _ai_perm.can_use_room_ai(request.user):\n            return JsonResponse({"ok": False, "error": "Raum-KI ist für deine Rolle nicht freigeschaltet."}, status=403)\n        if not _ai_perm.project_allowed(request.user, organization, project_pk):\n            return JsonResponse({"ok": False, "error": "Projekt nicht gefunden."}, status=404)\n        return _ab_role_original_room_planner_ai(request, project_pk)\n'
TEST_CODE = 'import json\nfrom unittest import mock\nfrom datetime import timedelta\n\nfrom django.contrib.auth.models import User\nfrom django.contrib.sessions.middleware import SessionMiddleware\nfrom django.http import JsonResponse\nfrom django.test import Client, RequestFactory, TestCase\nfrom django.urls import reverse\nfrom django.utils import timezone\n\nfrom erp import ai_role_permissions as perms\nfrom erp import assistant_views, field_authorization_views, room_planner_views\nfrom erp.models import CalendarEvent, Customer, Employee, Organization, Project, UserProfile\n\n\nclass AIRolePermissionHardeningTests(TestCase):\n    def setUp(self):\n        self.org = Organization.objects.create(name="KI RBAC Test")\n\n        self.admin = self._user("admin-ai", UserProfile.Role.ADMIN)\n        self.office = self._user("office-ai", UserProfile.Role.OFFICE)\n        self.accounting = self._user("accounting-ai", UserProfile.Role.ACCOUNTING)\n        self.pm = self._user("pm-ai", UserProfile.Role.PROJECT_MANAGER)\n        self.tech = self._user("tech-ai", UserProfile.Role.TECHNICIAN)\n        self.other = self._user("other-ai", UserProfile.Role.TECHNICIAN)\n        self.readonly = self._user("readonly-ai", UserProfile.Role.READONLY)\n\n        self.pm_employee = self._employee(self.pm, "M-PM", "Paula", "Leitung")\n        self.tech_employee = self._employee(self.tech, "M-TECH", "Tom", "Monteur")\n        self.other_employee = self._employee(self.other, "M-OTHER", "Otto", "Fremd")\n\n        self.assigned_customer = Customer.objects.create(\n            organization=self.org, number="K-ASSIGNED", company="Assigned Kunde"\n        )\n        self.secret_customer = Customer.objects.create(\n            organization=self.org, number="K-SECRET", company="Secret Kunde"\n        )\n        self.assigned_project = Project.objects.create(\n            organization=self.org, number="P-ASSIGNED", title="Assigned Bad",\n            customer=self.assigned_customer, manager=self.pm_employee, status="in_progress"\n        )\n        self.assigned_project.members.add(self.tech_employee)\n        self.secret_project = Project.objects.create(\n            organization=self.org, number="P-SECRET", title="Secret Villa",\n            customer=self.secret_customer, manager=self.other_employee, status="in_progress"\n        )\n        now = timezone.now()\n        self.assigned_event = CalendarEvent.objects.create(\n            organization=self.org, project=self.assigned_project, title="Assigned Einsatz",\n            starts_at=now, ends_at=now + timedelta(hours=1), type="site"\n        )\n        self.assigned_event.attendees.add(self.tech_employee)\n        self.secret_event = CalendarEvent.objects.create(\n            organization=self.org, project=self.secret_project, title="Secret Einsatz",\n            starts_at=now, ends_at=now + timedelta(hours=1), type="site"\n        )\n        self.secret_event.attendees.add(self.other_employee)\n\n    def _user(self, username, role):\n        user = User.objects.create_user(username=username, password="safe-test-password", email=f"{username}@example.test")\n        user.profile.organization = self.org\n        user.profile.role = role\n        user.profile.is_mobile_worker = role == UserProfile.Role.TECHNICIAN\n        user.profile.save()\n        return user\n\n    def _employee(self, user, number, first, last):\n        return Employee.objects.create(\n            organization=self.org, user=user, employee_number=number,\n            first_name=first, last_name=last, email=user.email, active=True\n        )\n\n    def _request(self, user, path="/assistant/command/"):\n        request = RequestFactory().post(path, data={})\n        request.user = user\n        middleware = SessionMiddleware(lambda req: None)\n        middleware.process_request(request)\n        request.session.save()\n        return request\n\n    def test_technician_entity_search_is_assignment_scoped(self):\n        assigned = perms.entity_search_context(self.tech, self.org, "Assigned")\n        secret = perms.entity_search_context(self.tech, self.org, "Secret")\n        self.assertTrue(any(item["id"] == self.assigned_project.pk and item["route"] == "projects" for item in assigned))\n        self.assertTrue(any(item["id"] == self.assigned_customer.pk and item["route"] == "customers" for item in assigned))\n        self.assertFalse(any(item["id"] == self.secret_project.pk for item in secret))\n        self.assertFalse(any(item["id"] == self.secret_customer.pk for item in secret))\n        self.assertFalse(any(item["id"] == self.other_employee.pk for item in secret))\n\n    def test_project_manager_scope_does_not_include_unassigned_project(self):\n        self.assertTrue(perms.project_allowed(self.pm, self.org, self.assigned_project.pk))\n        self.assertFalse(perms.project_allowed(self.pm, self.org, self.secret_project.pk))\n        matches = perms.entity_search_context(self.pm, self.org, "Secret")\n        self.assertFalse(any(item["id"] == self.secret_project.pk for item in matches))\n\n    def test_non_commercial_roles_never_send_price_context_to_ki(self):\n        payload = {\n            "message": "Dokumentiere den Einsatz",\n            "path": f"/projects/{self.assigned_project.pk}/",\n            "fields": [\n                {"name": "description", "label": "Beschreibung", "value": "Bad"},\n                {"name": "unit_price", "label": "Verkaufspreis", "value": "999.00"},\n                {"name": "purchase_price", "label": "Einkauf", "value": "500.00"},\n                {\n                    "name": "customer", "label": "Kunde", "value": str(self.assigned_customer.pk),\n                    "options": [\n                        {"value": str(self.assigned_customer.pk), "label": "Assigned Kunde"},\n                        {"value": str(self.secret_customer.pk), "label": "Secret Kunde"},\n                    ],\n                },\n            ],\n            "catalog": [{"name": "Waschtisch", "code": "X1", "unit": "Stk.", "price": "1234.56", "purchase_price": "800"}],\n            "history": [{"role": "assistant", "content": "Secret price was 1234 EUR"}],\n        }\n        safe = perms.sanitize_assistant_payload(self.tech, self.org, payload)\n        names = {field["name"] for field in safe["fields"]}\n        self.assertIn("description", names)\n        self.assertNotIn("unit_price", names)\n        self.assertNotIn("purchase_price", names)\n        customer = next(field for field in safe["fields"] if field["name"] == "customer")\n        self.assertEqual([option["value"] for option in customer["options"]], [str(self.assigned_customer.pk)])\n        self.assertNotIn("price", safe["catalog"][0])\n        self.assertNotIn("purchase_price", safe["catalog"][0])\n        self.assertEqual(safe["history"], [])\n\n    def test_price_request_is_rejected_before_llm_for_technician(self):\n        client = Client()\n        self.assertTrue(client.login(username=self.tech.username, password="safe-test-password"))\n        with mock.patch.object(assistant_views, "_create_response") as provider:\n            response = client.post(\n                reverse("next-assistant-command"),\n                data=json.dumps({"message": "Wie hoch ist der Verkaufspreis und die Marge?", "path": "/field/", "fields": [], "catalog": []}),\n                content_type="application/json",\n            )\n        self.assertEqual(response.status_code, 403)\n        self.assertIn("Preisdaten", response.json()["error"])\n        provider.assert_not_called()\n\n    def test_forged_actions_are_filtered_again_server_side(self):\n        safe_payload = {\n            "fields": [{"name": "description", "label": "Beschreibung", "value": ""}],\n            "catalog": [{"name": "Material", "code": "A"}],\n        }\n        actions = [\n            {"type": "set_field", "target": "unit_price", "value": "999", "count": 0},\n            {"type": "navigate", "target": "invoices", "value": "", "count": 0},\n            {"type": "navigate_record", "target": "projects", "value": str(self.secret_project.pk), "count": 0},\n            {"type": "navigate_record", "target": "projects", "value": str(self.assigned_project.pk), "count": 0},\n            {"type": "set_field", "target": "description", "value": "OK", "count": 0},\n        ]\n        filtered = perms.filter_actions(self.tech, self.org, safe_payload, actions)\n        self.assertEqual(\n            [(item["type"], item["target"]) for item in filtered],\n            [("navigate_record", "projects"), ("set_field", "description")],\n        )\n        self.assertEqual(filtered[0]["value"], str(self.assigned_project.pk))\n\n    def test_old_admin_session_matches_are_requeried_after_role_downgrade(self):\n        request = self._request(self.tech)\n        request.session["kayi_ai_entity_state"] = {\n            "query": "Secret",\n            "matches": [{"route": "projects", "id": self.secret_project.pk, "label": "Secret Villa"}],\n            "role": "admin",\n        }\n        request.session.save()\n        result = assistant_views._resolve_entity_search(request, self.org, "project")\n        self.assertEqual(result["query"], "Secret")\n        self.assertEqual(result["matches"], [])\n        self.assertEqual(request.session["kayi_ai_entity_state"]["role"], "technician")\n\n    def test_field_ai_strips_catalog_sales_prices_for_technician(self):\n        request = self._request(self.tech, f"/appointments/{self.assigned_event.pk}/authorization/ai/")\n        fake = JsonResponse({\n            "ok": True,\n            "summary": "Vorschlag",\n            "positions": [{\n                "description": "Waschtisch",\n                "quantity": "1",\n                "unit": "Stk.",\n                "unit_price": "999.00",\n                "sales_price": "999.00",\n                "purchase_price": "400.00",\n                "tax_rate": "19.00",\n                "margin": "599.00",\n            }],\n        })\n        with mock.patch.object(field_authorization_views, "_ab_role_original_authorization_ai", return_value=fake):\n            response = field_authorization_views.authorization_ai(request, self.assigned_event.pk)\n        self.assertEqual(response.status_code, 200)\n        body = response.json()\n        position = body["positions"][0]\n        for forbidden in ("unit_price", "sales_price", "purchase_price", "tax_rate", "margin"):\n            self.assertNotIn(forbidden, position)\n        self.assertTrue(body["pricing_locked"])\n        self.assertTrue(body["requires_office_pricing"])\n\n    def test_voice_ai_cannot_probe_another_technicians_event(self):\n        request = self._request(self.tech, f"/appointments/{self.secret_event.pk}/voice/")\n        with mock.patch.object(assistant_views, "_ab_role_original_appointment_voice") as original:\n            response = assistant_views.appointment_voice(request, self.secret_event.pk)\n        self.assertEqual(response.status_code, 404)\n        original.assert_not_called()\n\n    def test_room_ai_cannot_probe_unassigned_project(self):\n        request = self._request(self.pm, f"/configurator/?project={self.secret_project.pk}")\n        with mock.patch.object(room_planner_views, "_ab_role_original_room_planner_vision") as original:\n            response = room_planner_views.room_planner_vision(request, self.secret_project.pk)\n        self.assertEqual(response.status_code, 404)\n        original.assert_not_called()\n\n    def test_admin_office_accounting_keep_commercial_ai_permission(self):\n        for user in (self.admin, self.office, self.accounting):\n            with self.subTest(role=perms.role_for(user)):\n                self.assertTrue(perms.can_view_prices(user))\n                payload = {\n                    "fields": [{"name": "unit_price", "label": "Preis", "value": "123"}],\n                    "catalog": [{"name": "X", "price": "123"}],\n                }\n                safe = perms.sanitize_assistant_payload(user, self.org, payload)\n                self.assertEqual(safe["fields"][0]["value"], "123")\n\n    def test_readonly_ai_cannot_mutate_drafts(self):\n        payload = {"fields": [{"name": "description", "label": "Beschreibung", "value": ""}], "catalog": []}\n        actions = [{"type": "set_field", "target": "description", "value": "x", "count": 0}]\n        self.assertEqual(perms.filter_actions(self.readonly, self.org, payload, actions), [])\n'


def read(rel: str) -> str:
    path = ROOT / rel
    if not path.exists():
        raise RuntimeError(f"AI role hardening target missing: {rel}")
    return path.read_text(encoding="utf-8")


def write(rel: str, text: str) -> None:
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def append_once(rel: str, addition: str) -> None:
    text = read(rel)
    if MARKER in text:
        return
    write(rel, text.rstrip() + "\n\n" + addition.strip() + "\n")


def install() -> None:
    # Central permission module is regenerated on every deterministic assembly.
    write("erp/ai_role_permissions.py", AI_ROLE_MODULE)
    append_once("erp/assistant_views.py", ASSISTANT_APPEND)
    append_once("erp/field_authorization_views.py", FIELD_APPEND)
    append_once("erp/room_planner_views.py", ROOM_APPEND)
    write("tests/test_ai_role_permissions.py", TEST_CODE)

    checks = {
        "erp/ai_role_permissions.py": [
            "sanitize_assistant_payload",
            "entity_search_context",
            "filter_actions",
            "project_allowed",
            "event_allowed",
            "strip_sensitive_data",
        ],
        "erp/assistant_views.py": [
            MARKER,
            "_ai_perm.is_price_request",
            "_ai_perm.sanitize_assistant_payload",
            "_ai_perm.filter_actions",
            "_ai_perm.event_allowed",
        ],
        "erp/field_authorization_views.py": [
            MARKER,
            "_ai_perm.strip_sensitive_data",
            "requires_office_pricing",
        ],
        "erp/room_planner_views.py": [
            MARKER,
            "_ai_perm.project_allowed",
            "_ai_perm.can_use_room_ai",
        ],
        "tests/test_ai_role_permissions.py": [
            "test_price_request_is_rejected_before_llm_for_technician",
            "test_old_admin_session_matches_are_requeried_after_role_downgrade",
            "test_field_ai_strips_catalog_sales_prices_for_technician",
        ],
    }
    missing = []
    for rel, markers in checks.items():
        text = read(rel)
        for marker in markers:
            if marker not in text:
                missing.append(f"{rel}: {marker}")
    if missing:
        raise RuntimeError("AI role permission final guard failed: " + "; ".join(missing))

    print("A+Bau KI role permissions installed: role-scoped DB search, no field price leakage, action revalidation and scoped voice/room AI.")


install()
